-- Migración 0009. Las medidas del tipo de lote pasan al catálogo UNIDADES.
-- LOTES_TIPOS_UNIDADES relaciona cada tipo con las unidades en que puede medir producto.
-- No editar este archivo. El siguiente cambio va en una migración nueva
-- y debe reflejarse en db/init.sql.

BEGIN;

CREATE TABLE "UNIDADES" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CODIGO" text NOT NULL UNIQUE,
  "NOMBRE" text NOT NULL,
  "ACTIVO" boolean NOT NULL DEFAULT true,
  "ES_SEMILLA" boolean NOT NULL DEFAULT false,
  "ENTERA" boolean NOT NULL DEFAULT false
);

INSERT INTO "UNIDADES" ("CODIGO", "NOMBRE", "ES_SEMILLA", "ENTERA") VALUES
  ('unidad', 'Unidad', true, true),
  ('litro', 'Litro', true, false),
  ('kilo', 'Kilo', true, false);

CREATE TABLE "LOTES_TIPOS_UNIDADES" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ID_TIPO" integer NOT NULL,
  "ID_UNIDAD" integer NOT NULL,
  "ES_SEMILLA" boolean NOT NULL DEFAULT false,
  CONSTRAINT "LOTES_TIPOS_UNIDADES_ID_TIPO_FK"
    FOREIGN KEY ("ID_TIPO") REFERENCES "LOTES_TIPOS" ("ID"),
  CONSTRAINT "LOTES_TIPOS_UNIDADES_ID_UNIDAD_FK"
    FOREIGN KEY ("ID_UNIDAD") REFERENCES "UNIDADES" ("ID"),
  CONSTRAINT "LOTES_TIPOS_UNIDADES_PAR_UQ" UNIQUE ("ID_TIPO", "ID_UNIDAD")
);

CREATE INDEX "LOTES_TIPOS_UNIDADES_ID_UNIDAD_IDX"
  ON "LOTES_TIPOS_UNIDADES" ("ID_UNIDAD");

INSERT INTO "LOTES_TIPOS_UNIDADES" ("ID_TIPO", "ID_UNIDAD", "ES_SEMILLA")
SELECT tipo."ID", unidad."ID", tipo."ES_SEMILLA"
FROM "LOTES_TIPOS" AS tipo
JOIN "UNIDADES" AS unidad ON (
  (tipo."MIDE_UNIDAD" AND unidad."CODIGO" = 'unidad')
  OR (tipo."MIDE_LITRO" AND unidad."CODIGO" = 'litro')
  OR (tipo."MIDE_KILO" AND unidad."CODIGO" = 'kilo')
);

ALTER TABLE "LOTES_PRODUCTOS"
  ADD COLUMN "ID_UNIDAD" integer;

UPDATE "LOTES_PRODUCTOS" AS producto
SET "ID_UNIDAD" = unidad."ID"
FROM "UNIDADES" AS unidad
WHERE unidad."CODIGO" = producto."UNIDAD_MEDIDA";

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM "LOTES_PRODUCTOS" WHERE "ID_UNIDAD" IS NULL) THEN
    RAISE EXCEPTION 'hay productos con una unidad de medida desconocida';
  END IF;
END $$;

ALTER TABLE "LOTES_PRODUCTOS"
  ALTER COLUMN "ID_UNIDAD" SET NOT NULL;

ALTER TABLE "LOTES_PRODUCTOS"
  DROP CONSTRAINT "LOTES_PRODUCTOS_UNIDAD_MEDIDA_CHK",
  DROP CONSTRAINT "LOTES_PRODUCTOS_UNIDAD_ENTERA_CHK",
  DROP COLUMN "UNIDAD_MEDIDA";

ALTER TABLE "LOTES_PRODUCTOS"
  ADD CONSTRAINT "LOTES_PRODUCTOS_ID_UNIDAD_FK"
  FOREIGN KEY ("ID_UNIDAD") REFERENCES "UNIDADES" ("ID");

CREATE INDEX "LOTES_PRODUCTOS_ID_UNIDAD_IDX" ON "LOTES_PRODUCTOS" ("ID_UNIDAD");

CREATE OR REPLACE FUNCTION unidades_validar()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW."ENTERA" AND EXISTS (
    SELECT 1
    FROM "LOTES_PRODUCTOS"
    WHERE "ID_UNIDAD" = NEW."ID"
      AND "CANTIDAD" <> trunc("CANTIDAD")
  ) THEN
    RAISE EXCEPTION 'hay cantidades fraccionarias para esta unidad' USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER "UNIDADES_ENTERA_TRG"
  BEFORE UPDATE ON "UNIDADES"
  FOR EACH ROW
  EXECUTE FUNCTION unidades_validar();

CREATE OR REPLACE FUNCTION lotes_tipos_unidades_validar()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  es_final boolean;
BEGIN
  IF TG_OP <> 'DELETE' THEN
    SELECT "ES_FINAL" INTO es_final
    FROM "LOTES_TIPOS"
    WHERE "ID" = NEW."ID_TIPO";

    IF es_final IS NULL THEN
      RAISE EXCEPTION 'tipo de lote inexistente' USING ERRCODE = '23503';
    END IF;

    IF NOT es_final THEN
      RAISE EXCEPTION 'un tipo que no es final no mide producto' USING ERRCODE = '23514';
    END IF;
  END IF;

  IF TG_OP = 'DELETE' OR (
    TG_OP = 'UPDATE'
    AND (
      NEW."ID_TIPO" IS DISTINCT FROM OLD."ID_TIPO"
      OR NEW."ID_UNIDAD" IS DISTINCT FROM OLD."ID_UNIDAD"
    )
  ) THEN
    IF EXISTS (
      SELECT 1
      FROM "LOTES" AS lote
      JOIN "LOTES_PRODUCTOS" AS producto ON producto."ID_LOTE" = lote."ID"
      WHERE lote."ID_TIPO" = OLD."ID_TIPO"
        AND producto."ID_UNIDAD" = OLD."ID_UNIDAD"
    ) THEN
      RAISE EXCEPTION 'hay productos con una medida que el tipo ya no permite' USING ERRCODE = '23514';
    END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER "LOTES_TIPOS_UNIDADES_TRG"
  BEFORE INSERT OR UPDATE OR DELETE ON "LOTES_TIPOS_UNIDADES"
  FOR EACH ROW
  EXECUTE FUNCTION lotes_tipos_unidades_validar();

CREATE OR REPLACE FUNCTION lotes_validar()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  tipo_final boolean;
  padre_final boolean;
BEGIN
  SELECT "ES_FINAL" INTO tipo_final
  FROM "LOTES_TIPOS"
  WHERE "ID" = NEW."ID_TIPO";

  IF tipo_final IS NULL THEN
    RAISE EXCEPTION 'tipo de lote inexistente' USING ERRCODE = '23503';
  END IF;

  IF tipo_final THEN
    IF NEW."ID_UNIDAD" IS NOT NULL THEN
      RAISE EXCEPTION 'un lote final no se embarca en la unidad' USING ERRCODE = '23514';
    END IF;

    IF NEW."PADRE_ID" IS NOT NULL THEN
      SELECT tipo."ES_FINAL" INTO padre_final
      FROM "LOTES" AS padre
      JOIN "LOTES_TIPOS" AS tipo ON tipo."ID" = padre."ID_TIPO"
      WHERE padre."ID" = NEW."PADRE_ID";

      IF padre_final IS NULL THEN
        RAISE EXCEPTION 'lote padre inexistente' USING ERRCODE = '23503';
      END IF;

      IF padre_final THEN
        RAISE EXCEPTION 'una categoria final no contiene lotes' USING ERRCODE = '23514';
      END IF;
    END IF;

    IF TG_OP = 'UPDATE' AND NEW."ID_TIPO" IS DISTINCT FROM OLD."ID_TIPO" THEN
      IF EXISTS (SELECT 1 FROM "LOTES" WHERE "PADRE_ID" = NEW."ID") THEN
        RAISE EXCEPTION 'una categoria final no contiene lotes' USING ERRCODE = '23514';
      END IF;

      IF EXISTS (
        SELECT 1
        FROM "LOTES_PRODUCTOS" AS producto
        WHERE producto."ID_LOTE" = NEW."ID"
          AND NOT EXISTS (
            SELECT 1
            FROM "LOTES_TIPOS_UNIDADES" AS relacion
            WHERE relacion."ID_TIPO" = NEW."ID_TIPO"
              AND relacion."ID_UNIDAD" = producto."ID_UNIDAD"
          )
      ) THEN
        RAISE EXCEPTION 'la medida del producto no corresponde al tipo de lote' USING ERRCODE = '23514';
      END IF;
    END IF;
  ELSE
    IF NEW."PADRE_ID" IS NOT NULL THEN
      RAISE EXCEPTION 'solo un lote final puede ir dentro de otro lote' USING ERRCODE = '23514';
    END IF;

    IF EXISTS (SELECT 1 FROM "LOTES_PRODUCTOS" WHERE "ID_LOTE" = NEW."ID") THEN
      RAISE EXCEPTION 'un lote que no es final no contiene productos' USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION lotes_productos_validar()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  es_final boolean;
  entera boolean;
BEGIN
  SELECT tipo."ES_FINAL" INTO es_final
  FROM "LOTES" AS lote
  JOIN "LOTES_TIPOS" AS tipo ON tipo."ID" = lote."ID_TIPO"
  WHERE lote."ID" = NEW."ID_LOTE";

  IF es_final IS NULL THEN
    RAISE EXCEPTION 'lote inexistente' USING ERRCODE = '23503';
  END IF;

  IF NOT es_final THEN
    RAISE EXCEPTION 'solo un lote final contiene productos' USING ERRCODE = '23514';
  END IF;

  SELECT "ENTERA" INTO entera
  FROM "UNIDADES"
  WHERE "ID" = NEW."ID_UNIDAD";

  IF entera IS NULL THEN
    RAISE EXCEPTION 'unidad inexistente' USING ERRCODE = '23503';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM "LOTES" AS lote
    JOIN "LOTES_TIPOS_UNIDADES" AS relacion ON relacion."ID_TIPO" = lote."ID_TIPO"
    WHERE lote."ID" = NEW."ID_LOTE"
      AND relacion."ID_UNIDAD" = NEW."ID_UNIDAD"
  ) THEN
    RAISE EXCEPTION 'la medida del producto no corresponde al tipo de lote' USING ERRCODE = '23514';
  END IF;

  IF entera AND NEW."CANTIDAD" <> trunc(NEW."CANTIDAD") THEN
    RAISE EXCEPTION 'la cantidad de esta unidad debe ser entera' USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION lotes_tipos_validar()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NOT NEW."ES_FINAL" AND EXISTS (
    SELECT 1
    FROM "LOTES" AS lote
    JOIN "LOTES_PRODUCTOS" AS producto ON producto."ID_LOTE" = lote."ID"
    WHERE lote."ID_TIPO" = NEW."ID"
  ) THEN
    RAISE EXCEPTION 'el tipo tiene productos y debe seguir siendo final' USING ERRCODE = '23514';
  END IF;

  IF NEW."ES_FINAL" AND EXISTS (
    SELECT 1
    FROM "LOTES" AS hijo
    JOIN "LOTES" AS padre ON padre."ID" = hijo."PADRE_ID"
    WHERE padre."ID_TIPO" = NEW."ID"
  ) THEN
    RAISE EXCEPTION 'el tipo contiene lotes y no puede ser final' USING ERRCODE = '23514';
  END IF;

  IF NOT NEW."ES_FINAL" AND EXISTS (
    SELECT 1 FROM "LOTES"
    WHERE "ID_TIPO" = NEW."ID" AND "PADRE_ID" IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'un tipo no final no puede estar dentro de otro lote' USING ERRCODE = '23514';
  END IF;

  IF NOT NEW."ES_FINAL" AND EXISTS (
    SELECT 1 FROM "LOTES_TIPOS_UNIDADES" WHERE "ID_TIPO" = NEW."ID"
  ) THEN
    RAISE EXCEPTION 'un tipo que no es final no mide producto' USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;

ALTER TABLE "LOTES_TIPOS"
  DROP CONSTRAINT "LOTES_TIPOS_MEDIDA_CHK";

ALTER TABLE "LOTES_TIPOS"
  DROP COLUMN "MIDE_UNIDAD",
  DROP COLUMN "MIDE_LITRO",
  DROP COLUMN "MIDE_KILO";

ALTER TABLE "UNIDADES" OWNER TO packing;
ALTER TABLE "LOTES_TIPOS_UNIDADES" OWNER TO packing;
ALTER FUNCTION unidades_validar() OWNER TO packing;
ALTER FUNCTION lotes_tipos_unidades_validar() OWNER TO packing;
ALTER FUNCTION lotes_validar() OWNER TO packing;
ALTER FUNCTION lotes_productos_validar() OWNER TO packing;
ALTER FUNCTION lotes_tipos_validar() OWNER TO packing;

COMMIT;
